      es: ["Construida por el emperador mogol Aurangzeb.", "Fue la mezquita más grande del mundo durante más de 300 años."],
      pt: ["Construída pelo imperador mogol Aurangzeb.", "Foi a maior mesquita do mundo durante mais de 300 anos."],
      fr: ["Construite par l'empereur moghol Aurangzeb.", "A été la plus grande mosquée du monde pendant plus de 300 ans."],
